// most recent content, so concurrent edits to different files are never
// lost or overwritten. Insertion order is used to write files in sequence.
let pendingWrites: Map<string, string>

const MAX_BUILD_TIME = 1000

export function writeFile(filepath: string, content: string) {
  cacheCommand(filepath, content)
  tryToWrite()
}

export function deleteFile(path: string) {
  fs.unlinkSync(path)
}

function cacheCommand(filepath: string, content: any) {
  if (DEBUG) {
    console.info(`caching ${filepath}: start`)
    if (pendingWrites.size) {
      const queued = Array.from(pendingWrites.keys()).join(', ')
      console.info(`caching ${filepath}: pending for ${queued}`)
    }
  }
  pendingWrites.set(filepath, content)
  if (DEBUG) console.info(`caching ${filepath}: end`)
}

function tryToWrite() {
  if (waitingForBuild) {
    if (DEBUG) console.info(`write: waiting for gatsby`)
    return
  }
  writeNextFile()
}

function writeNextFile() {
  const nextEntry = pendingWrites.keys().next()
  if (nextEntry.done) return

  const filepath = nextEntry.value
  const content = pendingWrites.get(filepath)
  pendingWrites.delete(filepath)

  if (DEBUG) console.info(`write ${filepath}: start`)

  const parentDir = path.dirname(filepath)
  if (!fs.existsSync(parentDir)) {
    fs.mkdirSync(parentDir, { recursive: true })
  }
  fs.writeFile(filepath, content, (err: any) => {
