const os = require('os')
const path = require('path')

let waitingForBuild = false
let pendingWrites = new Map()
const MAX_BUILD_TIME = 20

function writeFile(filepath, content) {
  cacheCommand(filepath, content)
  tryToWrite()
}

function cacheCommand(filepath, content) {
  pendingWrites.set(filepath, content)
}

function tryToWrite() {
  if (waitingForBuild) return
  writeNextFile()
}

function writeNextFile() {
  const nextEntry = pendingWrites.keys().next()
  if (nextEntry.done) return
  const filepath = nextEntry.value
  const content = pendingWrites.get(filepath)
  pendingWrites.delete(filepath)
  const parentDir = path.dirname(filepath)
  if (!fs.existsSync(parentDir)) fs.mkdirSync(parentDir, { recursive: true })
  fs.writeFile(filepath, content, err => {
    if (err) {
      waitingForBuild = false
      writeNextFile()
    } else {
      waitingForBuild = true
      setTimeout(() => {
        waitingForBuild = false
        writeNextFile()
      }, MAX_BUILD_TIME)
    }
  })
