const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'fwtest-'))
const a = path.join(dir, 'a.json')
const b = path.join(dir, 'b.json')
const c = path.join(dir, 'c.json')
const results = []

const prom = new Promise(resolve => {
  setTimeout(() => {
    results.push('final-a=' + fs.readFileSync(a, 'utf8'))
    results.push('final-b=' + fs.readFileSync(b, 'utf8'))
    results.push('final-c=' + fs.readFileSync(c, 'utf8'))
    resolve()
  }, 1000)
})

// Simulate two users editing concurrently:
// user1 writes A then A again (latest wins for same file)
// user2 writes B, then quickly A and C while a write build is pending.
writeFile(a, 'user1-A-v1')
writeFile(b, 'user2-B-v1')
callAll(writeFile, a, 'user2-A-v2')
callAll(writeFile, b, 'user2-B-v2')
callAll(writeFile, c, 'user2-C-v1')
callAll(writeFile, a, 'user1-A-v3')

// Keep issuing writes while builds are pending to test sequencing + dedupe.
setTimeout(() => callAll(writeFile, b, 'user2-B-v3'), 55)
setTimeout(() => callAll(writeFile, c, 'user2-C-v2'), 110)

function callAll(fn, ...args) {
  try {
    fn(...args)
  } catch (e) {
    results.push('ERROR: ' + e.message)
  }
}

prom.then(() => {
  console.log(results.join('\n'))
  const ok =
    results[0] === 'final-a=user1-A-v3' &&
    results[1] === 'final-b=user2-B-v3' &&
    results[2] === 'final-c=user2-C-v2'
  console.log(ok ? 'PASS' : 'FAIL')
  fs.rmSync(dir, { recursive: true, force: true })
})

