    if (this.props.escape) {
      this.documents.forEach(document =>
        document.addEventListener('keydown', this.handleEscape)
      )
    }
  }

  componentWillUnmount() {
    this.documents.forEach(document =>
      document.body.removeEventListener('click', this.handleDocumentClick)
