import { checkFilePathIsInRepo, updateRemoteToSSH } from './router'
import { openRepo } from './open-repo'

jest.mock('./open-repo')

const openRepoMock = openRepo as jest.Mock

describe('checkFilePathIsInRepo', () => {
  test('returns false if path not in repo', () => {
    const fileRelativePath = '../../../some-outside-file.json'
    const repoAbsPath = __dirname + '/..'
    expect(checkFilePathIsInRepo(fileRelativePath, repoAbsPath)).toBeFalsy()
  })

  test('returns true if path in repo', () => {
    const fileRelativePath = './some-inside-file.json'
    const repoAbsPath = __dirname + '/..'
    expect(checkFilePathIsInRepo(fileRelativePath, repoAbsPath)).toBeTruthy()
  })
})

describe('updateRemoteToSSH', () => {
  const repo = {
    getRemotes: jest.fn(),
    removeRemote: jest.fn(),
    addRemote: jest.fn(),
  }

  beforeEach(() => {
    repo.getRemotes.mockReset()
    repo.removeRemote.mockReset()
    repo.addRemote.mockReset()
    openRepoMock.mockReturnValue(repo)
  })

  test('does not throw when the repository has no remotes', async () => {
    repo.getRemotes.mockResolvedValue([])

    await expect(updateRemoteToSSH('/path/to/repo')).resolves.toBeUndefined()
  })

  test('does not remove or add a remote when the repository has no remotes', async () => {
    repo.getRemotes.mockResolvedValue([])

    await updateRemoteToSSH('/path/to/repo')

    expect(repo.removeRemote).not.toHaveBeenCalled()
    expect(repo.addRemote).not.toHaveBeenCalled()
  })

  test('converts an HTTP origin remote to SSH', async () => {
    repo.getRemotes.mockResolvedValue([
      { name: 'origin', refs: { fetch: 'https://github.com/user/repo.git' } },
    ])

    await updateRemoteToSSH('/path/to/repo')

    expect(repo.removeRemote).toHaveBeenCalledWith('origin')
    expect(repo.addRemote).toHaveBeenCalledWith(
      'origin',
      'git@github.com:user/repo.git'
    )
  })

  test('leaves an already-SSH origin remote unchanged', async () => {
    repo.getRemotes.mockResolvedValue([
      { name: 'origin', refs: { fetch: 'git@github.com:user/repo.git' } },
    ])

    await updateRemoteToSSH('/path/to/repo')

    expect(repo.removeRemote).not.toHaveBeenCalled()
    expect(repo.addRemote).not.toHaveBeenCalled()
  })
})

