/** Apache header */

import { Node } from 'prosemirror-model'
import { EditorState, Selection, Transaction } from 'prosemirror-state'
import { CellSelection } from 'prosemirror-tables'

/**
 * The position of a single cell within a table, along with the geometry needed
 * to place it on a rectangular grid.
 */
export interface CellInfo {
  /** The cell node. */
  node: Node
  /**
   * The document position of the start of this cell. This position resolves to
   * the boundary of the cell node inside the table row.
   */
  start: number
  /** The number of columns this cell spans. */
  colspan: number
  /** The number of rows this cell spans. */
  rowspan: number
  /** The column this cell begins in. */
  col: number
  /** The row this cell begins in. */
  row: number
}

export interface TableInfo {
  /** The table node. */
  node: Node
  /** The document position of the start of the table's content. */
  start: number
  /** The cells of the table indexed by row, with grid coordinates. */
  rows: CellInfo[][]
}

/**
 * Builds a rectangular representation of the cells in a table. The result
 * accounts for the `colspan` and `rowspan` attributes of every cell.
 *
 * @param table the table node to inspect
 * @param start the document position of the start of the table's content
 */
export function getTableInfo(table: Node, start: number): TableInfo {
  const rows: CellInfo[][] = []
  let rowIndex = 0

  table.forEach((row, offset) => {
    const rowStart = start + offset
    const cells: CellInfo[] = []
    let col = 0

    row.forEach((cell, cellOffset) => {
      cells.push({
        node: cell,
        start: rowStart + 1 + cellOffset,
        colspan: cell.attrs.colspan || 1,
        rowspan: cell.attrs.rowspan || 1,
        col,
        row: rowIndex,
      })
      col += cell.attrs.colspan || 1
    })

    rows.push(cells)
    rowIndex++
  })

  return {
    node: table,
    start,
    rows,
  }
}

/**
 * Locates the first ancestor `table` node of the current selection.
 */
export function findTable(state: EditorState): TableInfo | null {
  const $from = (state.selection as CellSelection).$anchorCell || state.selection.$from
  for (let depth = $from.depth; depth > 0; depth--) {
    const node = $from.node(depth)
    if ((node.type.spec as any).tableRole === 'table') {
      return getTableInfo(node, $from.start(depth))
    }
  }
  return null
}
