      this.handles.appendChild(handle)
      return handle
    })

    this.rowHandles = Array.from(Array(rowCount), (_, index) => {
      const handle = document.createElement('div')
      handle.className = 'handle handle-row'
      handle.addEventListener('mousedown', e => {
        e.preventDefault()
        e.stopPropagation()
        this.onSelectRow(index)
      })
      this.handles.appendChild(handle)
      return handle
    })
