import { Node } from 'prosemirror-model'
import { EditorState, Selection } from 'prosemirror-state'
import {
  CellSelection,
  deleteColumn as deleteTableColumn,
  deleteRow as deleteTableRow,
} from 'prosemirror-tables'

/**
 * A single cell within a table, along with the geometry needed to place it on
 * the rectangular grid of the table.
 */
export interface CellInfo {
  /** The cell node. */
  node: Node
  /**
   * The document position of the start of this cell. This position resolves to
   * the boundary of the cell node inside of the table row.
   */
  start: number
  /** The number of columns this cell spans. */
  colspan: number
  /** The number of rows this cell spans. */
  rowspan: number
  /** The column this cell begins in. */
  col: number
  /** The row this cell begins in. */
  row: number
}

export interface TableInfo {
  /** The table node. */
  node: Node
  /** The document position of the start of the table's content. */
  start: number
  /** The cells of the table, indexed by row. */
  rows: CellInfo[][]
}

/**
 * Builds a rectangular representation of the cells in a table. The result
 * accounts for the `colspan` and `rowspan` attributes of every cell.
 *
 * @param table the table node to inspect
 * @param start the document position of the start of the table's content
 */
export function getTableInfo(table: Node, start: number): TableInfo {
  const rows: CellInfo[][] = []
  let rowIndex = 0

  table.forEach((row, offset) => {
    const rowStart = start + offset
    const cells: CellInfo[] = []
    let col = 0

    row.forEach((cell, cellOffset) => {
      cells.push({
        node: cell,
        start: rowStart + 1 + cellOffset,
        colspan: cell.attrs.colspan || 1,
        rowspan: cell.attrs.rowspan || 1,
        col,
        row: rowIndex,
      })
      col += cell.attrs.colspan || 1
    })

    rows.push(cells)
    rowIndex++
  })

  return {
    node: table,
    start,
    rows,
  }
}

function isCellSelection(selection: Selection): selection is CellSelection {
  return selection instanceof CellSelection
}

/**
 * Locates the first ancestor `table` node of the current selection.
 */
export function findTable(state: EditorState): TableInfo | null {
  const $from = isCellSelection(state.selection)
    ? state.selection.$anchorCell
    : state.selection.$from

  for (let depth = $from.depth; depth > 0; depth--) {
    const node = $from.node(depth)
    if ((node.type.spec as any).tableRole === 'table') {
      return getTableInfo(node, $from.start(depth))
    }
  }

  return null
}

function cellAtStart(info: TableInfo, start: number): CellInfo | null {
  for (const row of info.rows) {
    for (const cell of row) {
      if (cell.start === start) return cell
    }
  }
  return null
}

/**
 * Returns every cell that covers the given column.
 */
export function columnCells(rows: CellInfo[][], index: number): CellInfo[] {
  const cells: CellInfo[] = []

  for (const row of rows) {
    for (const cell of row) {
      if (index >= cell.col && index < cell.col + cell.colspan) {
        cells.push(cell)
        break
      }
    }
  }

  return cells
}

/**
 * Returns every cell that covers the given row.
 */
export function rowCells(rows: CellInfo[][], index: number): CellInfo[] {
  return rows[index] || []
}

/**
 * Returns the cells covered by the current selection. When the selection is
 * not a `CellSelection` an empty array is returned.
 */
export function selectionCells(selection: Selection): CellInfo[] {
  if (!isCellSelection(selection)) return []

  const table = selection.$anchorCell.node(-1)
  if (!table) return []

  const info = getTableInfo(table, selection.$anchorCell.start(-1))
  const anchorCell = cellAtStart(info, selection.$anchorCell.pos)
  const headCell = cellAtStart(info, selection.$headCell.pos)
  if (!anchorCell || !headCell) return []

  const left = Math.min(anchorCell.col, headCell.col)
  const right = Math.max(
    anchorCell.col + anchorCell.colspan - 1,
    headCell.col + headCell.colspan - 1
  )
  const top = Math.min(anchorCell.row, headCell.row)
  const bottom = Math.max(
    anchorCell.row + anchorCell.rowspan - 1,
    headCell.row + headCell.rowspan - 1
  )

  const cells: CellInfo[] = []

  for (const row of info.rows) {
    for (const cell of row) {
      const cellRight = cell.col + cell.colspan - 1
      const cellBottom = cell.row + cell.rowspan - 1

      if (
        cell.col <= right &&
        cellRight >= left &&
        cell.row <= bottom &&
        cellBottom >= top
      ) {
        cells.push(cell)
      }
    }
  }

  return cells
}

/**
 * Returns true if the selection selects the cells of a single column.
 */
export function hasSelectedColumns(selection: Selection): boolean {
  if (!isCellSelection(selection)) return false

  const cells = selectionCells(selection)
  if (!cells.length) return false

  const col = cells[0].col
  return cells.every(cell => cell.col === col && cell.colspan === 1)
}

/**
 * Returns true if the selection selects the cells of a single row.
 */
export function hasSelectedRows(selection: Selection): boolean {
  if (!isCellSelection(selection)) return false

  const cells = selectionCells(selection)
  if (!cells.length) return false

  const row = cells[0].row
  return cells.every(cell => cell.row === row && cell.rowspan === 1)
}

/**
 * A command that selects all of the cells in a single column.
 */
export function selectColumn(
  index: number
): (state: EditorState, dispatch: any) => boolean {
  return (state, dispatch) => {
    const table = findTable(state)
    if (!table) return false

    const cells = columnCells(table.rows, index)
    if (!cells.length) return false

    const $anchorCell = state.doc.resolve(cells[0].start)
    const lastCell = cells[cells.length - 1]
    const $headCell = state.doc.resolve(lastCell.start)

    const selection = new CellSelection($anchorCell, $headCell)

    if (dispatch) {
      dispatch(state.tr.setSelection(selection))
    }

    return true
  }
}

/**
 * A command that selects all of the cells in a single row.
 */
export function selectRow(
  index: number
): (state: EditorState, dispatch: any) => boolean {
  return (state, dispatch) => {
    const table = findTable(state)
    if (!table) return false

    const cells = rowCells(table.rows, index)
    if (!cells.length) return false

    const $anchorCell = state.doc.resolve(cells[0].start)
    const lastCell = cells[cells.length - 1]
    const $headCell = state.doc.resolve(lastCell.start)

    const selection = new CellSelection($anchorCell, $headCell)

    if (dispatch) {
      dispatch(state.tr.setSelection(selection))
    }

    return true
  }
}

/**
 * A command that deletes the selected column(s) of the current table.
 */
export function deleteColumn(state: EditorState, dispatch: any): boolean {
  return deleteTableColumn(state, dispatch)
}

/**
 * A command that deletes the selected row(s) of the current table.
 */
export function deleteRow(state: EditorState, dispatch: any): boolean {
  return deleteTableRow(state, dispatch)
}

