import { Node } from 'prosemirror-model'
import { CellSelection } from 'prosemirror-tables'

import { PMTestHarness } from '../../prosemirror-test-utils'
import { defaultSchema } from '../default-schema'
import {
  deleteColumn,
  deleteRow,
  getTableInfo,
  hasSelectedColumns,
  hasSelectedRows,
  selectColumn,
  selectRow,
  selectionCells,
} from './table-commands'

function cell(type: 'th' | 'td', content: string): Node {
  const nodeType =
    type === 'th'
      ? defaultSchema.nodes.table_header
      : defaultSchema.nodes.table_cell

  return nodeType.create({}, defaultSchema.text(content))
}

function row(...cells: Node[]): Node {
  return defaultSchema.nodes.table_row.create({}, cells)
}

function table(...rows: Node[]): Node {
  return defaultSchema.nodes.table.create({}, rows)
}

/**
 * A table with a header row and two rows of data.
 *
 *  | h1 | h2 |
 *  | a  | b  |
 *  | c  | d  |
 */
function twoByTwoTable(): Node {
  return table(
    row(cell('th', 'h1'), cell('th', 'h2')),
    row(cell('td', 'a'), cell('td', 'b')),
    row(cell('td', 'c'), cell('td', 'd'))
  )
}

/**
 * The document position of the content of the first cell. The table is
 * expected to be the only child of the document.
 */
function firstCellContentPos(tableNode: Node): number {
  return getTableInfo(tableNode, 1).rows[0][0].start + 1
}

describe('table commands', () => {
  describe('selectColumn', () => {
    it('selects all of the cells in a column', () => {
      const harness = new PMTestHarness(defaultSchema)
      const t = twoByTwoTable()

      harness
        .forDoc(harness.doc(t))
        .withTextSelection(firstCellContentPos(t))

      harness.apply(selectColumn(0))

      expect(harness.state.selection).toBeInstanceOf(CellSelection)

      const cells = selectionCells(harness.state.selection)
      expect(cells.map(c => c.col)).toEqual([0, 0, 0])
      expect(cells.map(c => c.row)).toEqual([0, 1, 2])

      expect(hasSelectedColumns(harness.state.selection)).toBe(true)
      expect(hasSelectedRows(harness.state.selection)).toBe(false)
    })

    it('selects a column in the middle of the table', () => {
      const harness = new PMTestHarness(defaultSchema)
      const t = twoByTwoTable()

      harness
        .forDoc(harness.doc(t))
        .withTextSelection(firstCellContentPos(t))

      harness.apply(selectColumn(1))

      const cells = selectionCells(harness.state.selection)
      expect(cells.map(c => c.col)).toEqual([1, 1, 1])
    })

    it('does nothing outside of a table', () => {
      const harness = new PMTestHarness(defaultSchema)
      harness
        .forDoc(harness.doc(harness.p(harness.text('not a table'))))
        .withTextSelection(1)

      harness.shouldNotRun(selectColumn(0))
    })
  })

  describe('selectRow', () => {
    it('selects all of the cells in a row', () => {
      const harness = new PMTestHarness(defaultSchema)
      const t = twoByTwoTable()

      harness
        .forDoc(harness.doc(t))
        .withTextSelection(firstCellContentPos(t))

      harness.apply(selectRow(1))

      expect(harness.state.selection).toBeInstanceOf(CellSelection)

      const cells = selectionCells(harness.state.selection)
      expect(cells.map(c => c.col)).toEqual([0, 1])
      expect(cells.map(c => c.row)).toEqual([1, 1])

      expect(hasSelectedRows(harness.state.selection)).toBe(true)
      expect(hasSelectedColumns(harness.state.selection)).toBe(false)
    })

    it('selects the header row', () => {
      const harness = new PMTestHarness(defaultSchema)
      const t = twoByTwoTable()

      harness
        .forDoc(harness.doc(t))
        .withTextSelection(firstCellContentPos(t))

      harness.apply(selectRow(0))

      const cells = selectionCells(harness.state.selection)
      expect(cells.map(c => c.row)).toEqual([0, 0])
    })

    it('does nothing when the selection is outside of a table', () => {
      const harness = new PMTestHarness(defaultSchema)
      harness
        .forDoc(harness.doc(harness.p(harness.text('not a table'))))
        .withTextSelection(1)

      harness.shouldNotRun(selectRow(0))
    })
  })

  describe('deleteColumn', () => {
    it('deletes a column selected through the selection command', () => {
      const harness = new PMTestHarness(defaultSchema)
      const t = twoByTwoTable()

      harness
        .forDoc(harness.doc(t))
        .withTextSelection(firstCellContentPos(t))
        .apply(selectColumn(0))

      harness.apply(deleteColumn)

      harness.expect(
        harness.doc(
          table(
            row(cell('th', 'h2')),
            row(cell('td', 'b')),
            row(cell('td', 'd'))
          )
        )
      )
    })

    it('does nothing when the selection is not a cell selection', () => {
      const harness = new PMTestHarness(defaultSchema)
      const t = twoByTwoTable()

      harness
        .forDoc(harness.doc(t))
        .withTextSelection(firstCellContentPos(t))

      harness.shouldNotRun(deleteColumn)
    })
  })

  describe('deleteRow', () => {
    it('deletes a row selected through the selection command', () => {
      const harness = new PMTestHarness(defaultSchema)
      const t = twoByTwoTable()

      harness
        .forDoc(harness.doc(t))
        .withTextSelection(firstCellContentPos(t))
        .apply(selectRow(1))

      harness.apply(deleteRow)

      harness.expect(
        harness.doc(
          table(
            row(cell('th', 'h1'), cell('th', 'h2')),
            row(cell('td', 'c'), cell('td', 'd'))
          )
        )
      )
    })

    it('does nothing when the selection is not a cell selection', () => {
      const harness = new PMTestHarness(defaultSchema)
      const t = twoByTwoTable()

      harness
        .forDoc(harness.doc(t))
        .withTextSelection(firstCellContentPos(t))

      harness.shouldNotRun(deleteRow)
    })
  })
})

