import { EditorState, Plugin } from 'prosemirror-state'
import { Decoration, DecorationSet } from 'prosemirror-view'

import { selectionCells } from '../../commands/table-commands'

/**
 * A ProseMirror plugin that decorates all of the cells covered by a
 * `CellSelection`.
 *
 * Selecting a table column or a row through the table view handles drives a
 * `CellSelection`. This plugin paints the selected cells so that the extent of
 * the selection is always obvious to the user.
 */
export function cellSelection() {
  return new Plugin({
    props: {
      decorations(state: EditorState) {
        const cells = selectionCells(state.selection)
        if (!cells.length) return DecorationSet.empty

        return DecorationSet.create(
          state.doc,
          cells.map(cell =>
            Decoration.node(cell.start, cell.start + cell.node.nodeSize, {
              class: 'selectedCell',
            })
          )
        )
      },
    },
  })
}

