import * as React from 'react'
import styled from 'styled-components'
import { TrashIcon } from '@tinacms/icons'

export interface Position {
  top: number
  left: number
}

export interface FloatingTableMenuProps {
  /**
   * The position of the selected column or row handle, relative to the table
   * view the menu is rendered in.
   */
  position: Position
  /** Whether the selection is a column selection. */
  isColumnSelected: boolean
  /** Whether the selection is a row selection. */
  isRowSelected: boolean
  /** Called when the user confirms the deletion of the selected column. */
  onDeleteColumn(): void
  /** Called when the user confirms the deletion of the selected row. */
  onDeleteRow(): void
}

/**
 * A floating menu with a single delete button that appears next to a selected
 * table column or row.
 *
 * The menu anchors itself to the position of the selection handle. When
 * nothing meaningful is selected the menu renders `null`.
 */
export function FloatingTableMenu(props: FloatingTableMenuProps) {
  const { position, isColumnSelected, isRowSelected } = props

  if (!isColumnSelected && !isRowSelected) return null

  const label = isColumnSelected ? 'Delete column' : 'Delete row'
  const onDelete = isColumnSelected ? props.onDeleteColumn : props.onDeleteRow

  return (
    <FloatingMenu position={position} isColumnSelected={isColumnSelected}>
      <DeleteButton
        data-tooltip={label}
        onMouseDown={preventMouseDown}
        onClick={onDelete}
      >
        <TrashIcon />
      </DeleteButton>
    </FloatingMenu>
  )
}

function preventMouseDown(event: React.MouseEvent) {
  /**
   * The floating menu lives inside of the ProseMirror editor view. Prevent the
   * event from reaching the editor so interacting with the menu does not shift
   * the document selection.
   */
  event.preventDefault()
  event.stopPropagation()
}

const FloatingMenu = styled.div<{
  position: Position
  isColumnSelected: boolean
}>`
  position: absolute;
  z-index: 10;
  top: ${props => props.position.top}px;
  left: ${props => props.position.left}px;
  pointer-events: auto;
  transform: ${props =>
    props.isColumnSelected
      ? 'translate(-50%, -100%)'
      : 'translate(-100%, -50%)'};
`

const DeleteButton = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  background-color: #ffffff;
  border: 1px solid rgba(53, 50, 50, 0.09);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.12);
  cursor: pointer;
  outline: none;
  transition: background-color 85ms ease-out;

  &:hover {
    background-color: rgba(0, 132, 255, 0.08);
  }

  svg {
    width: 1.25rem;
    height: 1.25rem;
    fill: #433e52;
  }
`

