import * as React from 'react'
import { render as reactRender, unmountComponentAtNode } from 'react-dom'
import { Node } from 'prosemirror-model'
import { EditorView, NodeView } from 'prosemirror-view'

import { FloatingTableMenu } from '../../state/plugins/Menu/FloatingTableMenu'
import {
  deleteColumn,
  deleteRow,
  selectColumn,
  selectRow,
} from '../../commands/table-commands'

const HANDLE_SIZE = 12
const HANDLE_OVERLAP = 6

/**
 * The NodeView used to render `table` nodes in the Wysiwyg editor.
 *
 * In addition to the table itself this view renders a set of selection handles
 * (one for each column and row). Clicking a handle selects the corresponding
 * column or row, which in turn makes a small floating menu with a delete
 * button appear next to the selected handle.
 */
export class TableView implements NodeView {
  node: Node
  view: EditorView
  getPos: () => number

  dom: HTMLElement
  contentDOM: HTMLElement

  private table: HTMLTableElement
  private handlessDOM: HTMLElement
  private menuDOM: HTMLElement

  private columnHandles: HTMLElement[] = []
  private rowHandles: HTMLElement[] = []

  private columnCount = 0
  private rowCount = 0

  private selectedColumnIndex: number | null = null
  private selectedRowIndex: number | null = null

  private destroyed = false

  constructor(node: Node, view: EditorView, getPos: () => number) {
    this.node = node
    this.view = view
    this.getPos = getPos

    this.dom = document.createElement('div')
    this.dom.className = 'tina-table-view'

    this.table = document.createElement('table')
    this.table.className = 'tablesEditor'

    this.contentDOM = document.createElement('tbody')
    this.table.appendChild(this.contentDOM)
    this.dom.appendChild(this.table)

    this.handlessDOM = document.createElement('div')
    this.handlessDOM.className = 'table-handles'
    this.dom.appendChild(this.handlessDOM)

    this.menuDOM = document.createElement('div')
    this.menuDOM.className = 'table-float-menu'
    this.dom.appendChild(this.menuDOM)

    this.view.dom.addEventListener('mousedown', this.onEditorMouseDown)

    /**
     * The rows of the table are only rendered into the node view after it has
     * been mounted. Deferring the first measurement to the next frame ensures
     * the handles are created from the actual DOM.
     */
    this.scheduleUpdate()
  }

  /**
   * Recomputes the handle geometry on the next frame.
   */
  private scheduleUpdate() {
    if (typeof requestAnimationFrame === 'undefined') {
      this.refresh()
      return
    }
    requestAnimationFrame(() => this.refresh())
  }

  /**
   * Updates the selection handles and the floating menu to match the current
   * document.
   */
  private refresh() {
    if (this.destroyed) return

    this.createHandles()
    this.positionHandles()
    this.syncSelection()
    this.updateSelectedHandles()
    this.renderMenu()
  }

  /**
   * Creates one handle per column and one per row. Handles are only recreated
   * when the structure of the table has changed.
   */
  private createHandles() {
    if (!this.contentDOM) return

    const rows = this.contentDOM.querySelectorAll('tr')
    const columnCount = rows.length ? rows[0].querySelectorAll('th, td').length : 0
    const rowCount = rows.length

    if (columnCount === this.columnCount && rowCount === this.rowCount) return

    this.columnCount = columnCount
    this.rowCount = rowCount
    this.handlessDOM.innerHTML = ''
    this.columnHandles = []
    this.rowHandles = []

    if (!rowCount) return

    this.columnHandles = Array.from(Array(columnCount), (_, index) => {
      const handle = document.createElement('div')
      handle.className = 'handle handle-col'
      handle.addEventListener('mousedown', event => {
        event.preventDefault()
        event.stopPropagation()
        this.onSelectColumn(index)
      })
      this.handlessDOM.appendChild(handle)
      return handle
    })

    this.rowHandles = Array.from(Array(rowCount), (_, index) => {
      const handle = document.createElement('div')
      handle.className = 'handle handle-row'
      handle.addEventListener('mousedown', event => {
        event.preventDefault()
        event.stopPropagation()
        this.onSelectRow(index)
      })
      this.handlessDOM.appendChild(handle)
      return handle
    })
  }

  /**
   * Positions every handle over the column or row it represents.
   */
  private positionHandles() {
    if (!this.columnHandles.length && !this.rowHandles.length) return

    const wrapperRect = this.dom.getBoundingClientRect()
    const tableRect = this.table.getBoundingClientRect()

    const tableLeft = tableRect.left - wrapperRect.left
    const tableTop = tableRect.top - wrapperRect.top

    const rows = this.contentDOM.querySelectorAll('tr')
    const firstRowCells = rows.length ? rows[0].querySelectorAll('th, td') : []

    this.columnHandles.forEach((handle, index) => {
      const cell = firstRowCells[index]
      if (!cell) return

      const rect = cell.getBoundingClientRect()
      handle.style.top = `${tableTop - HANDLE_OVERLAP}px`
      handle.style.left = `${rect.left - wrapperRect.left}px`
      handle.style.width = `${rect.width}px`
      handle.style.height = `${HANDLE_SIZE}px`
    })

    this.rowHandles.forEach((handle, index) => {
      const row = rows[index]
      if (!row) return

      const rect = row.getBoundingClientRect()
      handle.style.top = `${rect.top - wrapperRect.top}px`
      handle.style.left = `${tableLeft - HANDLE_OVERLAP}px`
      handle.style.width = `${HANDLE_SIZE}px`
      handle.style.height = `${rect.height}px`
    })
  }

  /**
   * Clears the recorded selection when it no longer maps to a handle. This can
   * happen after the table is edited and a column or row is removed.
   */
  private syncSelection() {
    if (
      this.selectedColumnIndex !== null &&
      !this.columnHandles[this.selectedColumnIndex]
    ) {
      this.selectedColumnIndex = null
    }
    if (
      this.selectedRowIndex !== null &&
      !this.rowHandles[this.selectedRowIndex]
    ) {
      this.selectedRowIndex = null
    }
  }

  /**
   * Adds the `selected` class to the handle of the current selection.
   */
  private updateSelectedHandles() {
    this.columnHandles.forEach((handle, index) => {
      handle.classList.toggle('selected', index === this.selectedColumnIndex)
    })
    this.rowHandles.forEach((handle, index) => {
      handle.classList.toggle('selected', index === this.selectedRowIndex)
    })
  }

  /**
   * Renders the floating delete menu next to the selected handle.
   */
  private renderMenu() {
    const isColumnSelected = this.selectedColumnIndex !== null
    const isRowSelected = this.selectedRowIndex !== null

    if (!isColumnSelected && !isRowSelected) {
      unmountComponentAtNode(this.menuDOM)
      return
    }

    const handle = isColumnSelected
      ? this.columnHandles[this.selectedColumnIndex as number]
      : this.rowHandles[this.selectedRowIndex as number]

    if (!handle) {
      unmountComponentAtNode(this.menuDOM)
      return
    }

    const wrapperRect = this.dom.getBoundingClientRect()
    const handleRect = handle.getBoundingClientRect()

    reactRender(
      <FloatingTableMenu
        position={{
          top: handleRect.top - wrapperRect.top,
          left: handleRect.left - wrapperRect.left,
        }}
        isColumnSelected={isColumnSelected}
        isRowSelected={isRowSelected}
        onDeleteColumn={this.deleteSelectedColumn}
        onDeleteRow={this.deleteSelectedRow}
      />,
      this.menuDOM
    )
  }

  private onSelectColumn(index: number) {
    if (selectColumn(index)(this.view.state, this.view.dispatch)) {
      this.selectedColumnIndex = index
      this.selectedRowIndex = null
      this.updateSelectedHandles()
      this.renderMenu()
    }
  }

  private onSelectRow(index: number) {
    if (selectRow(index)(this.view.state, this.view.dispatch)) {
      this.selectedRowIndex = index
      this.selectedColumnIndex = null
      this.updateSelectedHandles()
      this.renderMenu()
    }
  }

  private deleteSelectedColumn = () => {
    if (deleteColumn(this.view.state, this.view.dispatch)) {
      this.clearSelection()
    }
  }

  private deleteSelectedRow = () => {
    if (deleteRow(this.view.state, this.view.dispatch)) {
      this.clearSelection()
    }
  }

  private clearSelection() {
    this.selectedColumnIndex = null
    this.selectedRowIndex = null
    this.updateSelectedHandles()
    this.renderMenu()
  }

  /**
   * When the user clicks outside of the table the recorded selection is
   * dropped so the floating menu disappears.
   */
  private onEditorMouseDown = (event: MouseEvent) => {
    if (
      this.selectedColumnIndex === null &&
      this.selectedRowIndex === null
    ) {
      return
    }

    const target = event.target as Node
    if (this.handlessDOM.contains(target) || this.menuDOM.contains(target)) {
      return
    }

    this.clearSelection()
  }

  update(node: Node) {
    if (node.type !== this.node.type) return false

    this.node = node
    this.scheduleUpdate()

    return true
  }

  stopEvent(event: any) {
    const target = event.target as Node
    return (
      this.handlessDOM.contains(target) || this.menuDOM.contains(target)
    )
  }

  ignoreMutation(mutation: MutationRecord) {
    return !this.contentDOM.contains(mutation.target)
  }

  destroy() {
    this.destroyed = true
    this.view.dom.removeEventListener('mousedown', this.onEditorMouseDown)
    unmountComponentAtNode(this.menuDOM)
  }
}

