  /* Tables */
  .ProseMirror table {
    border-collapse: collapse;
    table-layout: fixed;
    width: 100%;
  }

  .ProseMirror th,
  .ProseMirror td {
    border: 1px solid rgba(53, 50, 50, 0.15);
    padding: 0.375rem 0.75rem;
    vertical-align: top;
    position: relative;
  }

  .ProseMirror th {
    font-weight: 600;
    text-align: left;
    background-color: rgba(53, 50, 50, 0.05);
  }

  /* Cells covered by a cell selection */
  .ProseMirror .selectedCell:after {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    content: '';
    pointer-events: none;
    background-color: rgba(0, 132, 255, 0.12);
    z-index: 2;
  }

  /* Table view */
  .tina-table-view {
    position: relative;
  }

  .tina-table-view .tablesEditor {
    border: 1px solid rgba(53, 50, 50, 0.15);
    border-collapse: collapse;
    table-layout: fixed;
    width: 100%;
  }

  .table-handles {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 3;
    pointer-events: none;
  }

  .table-handles .handle {
    position: absolute;
    pointer-events: auto;
    border-radius: 3px;
    cursor: pointer;
    background-color: rgba(53, 50, 50, 0.3);
    transition: background-color 85ms ease-out;
  }

  .table-handles .handle:hover {
    background-color: rgba(53, 50, 50, 0.6);
  }

  .table-handles .handle.selected {
    background-color: #0084ff;
  }

  .table-handles .handle.handle-col {
    transform: translateY(-50%);
  }

  .table-handles .handle.handle-row {
    transform: translateX(-50%);
  }

  .table-float-menu {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 5;
    pointer-events: none;
  }
`

