/**
   * Clears the recorded selection when it no longer maps to a handle, or when
   * the editor selection no longer points at this table. This can happen after
   * the table is edited and a column or row is removed, or when the user moves
   * the cursor somewhere else in the document.
   */
  private syncSelection() {
    if (!selectionIsInTable(this.view.state.selection, this.node)) {
      this.selectedColumnIndex = null
      this.selectedRowIndex = null
      return
    }

    if (
      this.selectedColumnIndex !== null &&
